mapper.select:
select lauj.id, lauj.activity_id, lauj.status, lauj.create_user_id, lauj.update_user_id, lauj.create_time, lauj.update_time, lauj.user_id as userId, usee.nickname, usee.username, usee.avatar, usee.mobile, acti.name as activityName from la_activity_user_join lauj join la_user usee on lauj.user_id = usee.id join la_activity acti on lauj.activity_id = acti.id
and lauj.is_delete = 0
and lauj.activity_id = #{param.activityId}
and lauj.status = #{param.status}
and lauj.create_user_id = #{param.createUserId}
and lauj.update_user_id = #{param.updateUserId}
order by lauj.id desc
